const TECH_POOL = ["Snowflake", "Segment", "HubSpot", "Salesforce", "Outreach", "Gong"]

const mockEnrichment: EnrichmentProvider = {
  async enrichAccount(account, waterfall) {
    await sleep(800)
    const addTech = TECH_POOL.find((t) => !account.technologies.includes(t))
    return {
      patch: {
        employees: account.employees || 50,
        technologies: addTech ? [...account.technologies, addTech] : account.technologies,
        city: account.city || "San Francisco",
        description: account.description || `${account.name} is a ${account.industry} company headquartered in ${account.country}.`,
        linkedinUrl: account.linkedinUrl || `https://linkedin.com/company/${account.domain.split(".")[0]}`,
      },
      sources: waterfall.length ? waterfall.slice(0, 2) : ["Clearbit"],
    }
  },
  async findEmail(contact, domain) {
    await sleep(300)
    if (contact.email && contact.emailStatus !== "missing") {
      // Deterministic verification outcome based on the address.
      const bad = [...contact.email].reduce((h, c) => h + c.charCodeAt(0), 0) % 9 === 0
      return { email: contact.email, status: bad ? "invalid" : "verified" }
    }
    const local = `${contact.firstName}.${contact.lastName}`.toLowerCase().normalize("NFD").replace(/[^a-z.]/g, "")
    return { email: `${local}@${domain}`, status: "verified" }
  },
}

