const OPENERS = [
  "Quick thought after seeing your team's recent activity",
  "Noticed some momentum at your company this week",
  "Timely idea given what your team is working on",
]

const mockLlm: LlmProvider = {
  async draftOutreach({ account, contact, signal, senderName }) {
    await sleep(600)
    if (signal) {
      const title = signal.title.charAt(0).toLowerCase() + signal.title.slice(1)
      return {
        subject: `${account.name}: ${signal.title.toLowerCase()}`,
        body: `Hi ${contact.firstName},\n\nSaw that ${account.name} ${title} — ${signal.detail.toLowerCase()}. Teams in ${account.industry} at your stage often use this moment to tighten how they prioritize accounts.\n\nWe help ${contact.department} leaders route the right accounts to reps automatically using live fit + intent scoring. Open to a quick 15-minute look next week?\n\nBest,\n${senderName}`,
      }
    }
    return {
      subject: `${OPENERS[Math.floor(Math.random() * OPENERS.length)]}, ${contact.firstName}`,
      body: `Hi ${contact.firstName},\n\n${account.name} looks like it's investing in growth right now. Most ${account.industry} teams we work with see reps waste ~30% of their week on accounts that aren't ready to buy.\n\nWe fix that by scoring every account on fit + live intent and routing only the hot ones. Worth comparing notes for 15 minutes?\n\nCheers,\n${senderName}`,
    }
  },
  async suggestReply({ message, contact, senderName }) {
    await sleep(500)
    const name = contact?.firstName ?? "there"
    switch (message.sentiment) {
      case "positive":
        return `Hi ${name},\n\nGreat to hear! Here's my calendar — pick any slot that works this week: https://cal.example.com/${senderName.toLowerCase().split(" ")[0]}\n\nI'll send over a short agenda once it's booked.\n\nBest,\n${senderName}`
      case "negative":
        return `Hi ${name},\n\nUnderstood — I've removed you from our outreach. Apologies for the interruption.\n\nBest,\n${senderName}`
      case "ooo":
        return `Hi ${name},\n\nNo rush at all — I'll follow up when you're back.\n\nBest,\n${senderName}`
      default:
        return `Hi ${name},\n\nThanks for the pointer! Would you mind making a quick intro, or should I reach out directly?\n\nBest,\n${senderName}`
    }
  },
}

